import{_ as t,a0 as l,w as d,s as o,I as n,x as a,a1 as p,A as i,ao as r}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"树莓派自建 NAS 云盘之——树莓派搭建网络存储盘 | LCTT x X-CMD","titleTemplate":false,"description":"树莓派自建 NAS 云盘之——树莓派搭建网络存储盘 | LCTT (201810) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"树莓派自建 NAS 云盘之——树莓派搭建网络存储盘 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"树莓派自建 NAS 云盘之——树莓派搭建网络存储盘 | LCTT (201810) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201810/20180724 Building a network attached storage device with a Raspberry Pi","title":"树莓派自建 NAS 云盘之——树莓派搭建网络存储盘","tag":"201810","desc":""},"relativePath":"201810/20180724 Building a network attached storage device with a Raspberry Pi.md","filePath":"[post].md"}'),u={name:"201810/20180724 Building a network attached storage device with a Raspberry Pi.md"};function c(b,s,g,k,h,f){const e=l("Link");return d(),o("div",null,[s[31]||(s[31]=n("h1",{id:"树莓派自建-nas-云盘之——树莓派搭建网络存储盘",tabindex:"-1"},[a("树莓派自建 NAS 云盘之——树莓派搭建网络存储盘 "),n("a",{class:"header-anchor",href:"#树莓派自建-nas-云盘之——树莓派搭建网络存储盘","aria-label":"Permalink to “树莓派自建 NAS 云盘之——树莓派搭建网络存储盘”"},"​")],-1)),s[32]||(s[32]=n("blockquote",null,[n("p",null,"跟随这些逐步指导构建你自己的基于树莓派的 NAS 系统。")],-1)),s[33]||(s[33]=n("p",null,[n("img",{src:"https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/bus-storage.png?itok=95-zvHYl",alt:""})],-1)),n("p",null,[s[1]||(s[1]=a("我将在接下来的这三篇文章中讲述如何搭建一个简便、实用的 NAS 云盘系统。我在这个中心化的存储系统中存储数据，并且让它每晚都会自动的备份增量数据。本系列文章将利用 NFS 文件系统将磁盘挂载到同一网络下的不同设备上，使用 ",-1)),p(e,{href:"https://nextcloud.com/"},{default:i(()=>[...s[0]||(s[0]=[a("Nextcloud",-1)])]),_:1}),s[2]||(s[2]=a(" 来离线访问数据、分享数据。",-1))]),s[34]||(s[34]=n("p",null,"本文主要讲述将数据盘挂载到远程设备上的软硬件步骤。本系列第二篇文章将讨论数据备份策略、如何添加定时备份数据任务。最后一篇文章中我们将会安装 Nextcloud 软件，用户通过 Nextcloud 提供的 web 界面可以方便的离线或在线访问数据。本系列教程最终搭建的 NAS 云盘支持多用户操作、文件共享等功能，所以你可以通过它方便的分享数据，比如说你可以发送一个加密链接，跟朋友分享你的照片等等。",-1)),s[35]||(s[35]=n("p",null,"最终的系统架构如下图所示：",-1)),s[36]||(s[36]=n("p",null,[n("img",{src:"https://opensource.com/sites/default/files/uploads/nas_part1.png",alt:""})],-1)),s[37]||(s[37]=n("h3",{id:"硬件",tabindex:"-1"},[a("硬件 "),n("a",{class:"header-anchor",href:"#硬件","aria-label":"Permalink to “硬件”"},"​")],-1)),s[38]||(s[38]=n("p",null,"首先需要准备硬件。本文所列方案只是其中一种示例，你也可以按不同的硬件方案进行采购。",-1)),n("p",null,[s[4]||(s[4]=a("最主要的就是",-1)),p(e,{href:"https://www.raspberrypi.org/products/raspberry-pi-3-model-b/"},{default:i(()=>[...s[3]||(s[3]=[a("树莓派 3",-1)])]),_:1}),s[5]||(s[5]=a("，它带有四核 CPU、1G RAM，以及（比较）快速的网络接口。数据将存储在两个 USB 磁盘驱动器上（这里使用 1TB 磁盘）；其中一个磁盘用于每天数据存储，另一个用于数据备份。请务必使用有源 USB 磁盘驱动器或者带附加电源的 USB 集线器，因为树莓派无法为两个 USB 磁盘驱动器供电。",-1))]),s[39]||(s[39]=n("h3",{id:"软件",tabindex:"-1"},[a("软件 "),n("a",{class:"header-anchor",href:"#软件","aria-label":"Permalink to “软件”"},"​")],-1)),n("p",null,[s[9]||(s[9]=a("在该社区中最活跃的操作系统当属 ",-1)),p(e,{href:"https://www.raspbian.org/"},{default:i(()=>[...s[6]||(s[6]=[a("Raspbian",-1)])]),_:1}),s[10]||(s[10]=a("，便于定制个性化项目。已经有很多 ",-1)),p(e,{href:"https://www.raspberrypi.org/documentation/installation/installing-images/"},{default:i(()=>[...s[7]||(s[7]=[a("操作指南",-1)])]),_:1}),s[11]||(s[11]=a(" 讲述如何在树莓派中安装 Raspbian 系统，所以这里不再赘述。在撰写本文时，最新的官方支持版本是 ",-1)),p(e,{href:"https://www.raspberrypi.org/blog/raspbian-stretch/"},{default:i(()=>[...s[8]||(s[8]=[a("Raspbian Stretch",-1)])]),_:1}),s[12]||(s[12]=a("，它对我来说很好使用。",-1))]),s[40]||(s[40]=r(`<p>到此，我将假设你已经配置好了基本的 Raspbian 系统并且可以通过 <code>ssh</code> 访问到你的树莓派。</p><h3 id="准备-usb-磁盘驱动器" tabindex="-1">准备 USB 磁盘驱动器 <a class="header-anchor" href="#准备-usb-磁盘驱动器" aria-label="Permalink to “准备 USB 磁盘驱动器”">​</a></h3><p>为了更好地读写数据，我建议使用 ext4 文件系统去格式化磁盘。首先，你必须先找到连接到树莓派的磁盘。你可以在 <code>/dev/sd/&lt;x&gt;</code> 中找到磁盘设备。使用命令 <code>fdisk -l</code>，你可以找到刚刚连接的两块 USB 磁盘驱动器。请注意，操作下面的步骤将会清除 USB 磁盘驱动器上的所有数据，请做好备份。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>pi@raspberrypi:~ $ sudo fdisk -l</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&lt;...&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Disk /dev/sda: 931.5 GiB, 1000204886016 bytes, 1953525168 sectors</span></span>
<span class="line"><span>Units: sectors of 1 * 512 = 512 bytes</span></span>
<span class="line"><span>Sector size (logical/physical): 512 bytes / 512 bytes</span></span>
<span class="line"><span>I/O size (minimum/optimal): 512 bytes / 512 bytes</span></span>
<span class="line"><span>Disklabel type: dos</span></span>
<span class="line"><span>Disk identifier: 0xe8900690</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Device     Boot Start        End    Sectors   Size Id Type</span></span>
<span class="line"><span>/dev/sda1        2048 1953525167 1953523120 931.5G 83 Linux</span></span>
<span class="line"><span></span></span>
<span class="line"><span></span></span>
<span class="line"><span>Disk /dev/sdb: 931.5 GiB, 1000204886016 bytes, 1953525168 sectors</span></span>
<span class="line"><span>Units: sectors of 1 * 512 = 512 bytes</span></span>
<span class="line"><span>Sector size (logical/physical): 512 bytes / 512 bytes</span></span>
<span class="line"><span>I/O size (minimum/optimal): 512 bytes / 512 bytes</span></span>
<span class="line"><span>Disklabel type: dos</span></span>
<span class="line"><span>Disk identifier: 0x6aa4f598</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Device     Boot Start        End    Sectors   Size Id Type</span></span>
<span class="line"><span>/dev/sdb1  *     2048 1953521663 1953519616 931.5G  83 Linux</span></span></code></pre></div><p>由于这些设备是连接到树莓派的唯一的 1TB 的磁盘，所以我们可以很容易的辨别出 <code>/dev/sda</code> 和 <code>/dev/sdb</code> 就是那两个 USB 磁盘驱动器。每个磁盘末尾的分区表提示了在执行以下的步骤后如何查看，这些步骤将会格式化磁盘并创建分区表。为每个 USB 磁盘驱动器按以下步骤进行操作（假设你的磁盘也是 <code>/dev/sda</code> 和 <code>/dev/sdb</code>，第二次操作你只要替换命令中的 <code>sda</code> 为 <code>sdb</code> 即可）。</p><p>首先，删除磁盘分区表，创建一个新的并且只包含一个分区的新分区表。在 <code>fdisk</code> 中，你可以使用交互单字母命令来告诉程序你想要执行的操作。只需要在提示符 <code>Command(m for help):</code> 后输入相应的字母即可（可以使用 <code>m</code> 命令获得更多详细信息）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>pi@raspberrypi:~ $ sudo fdisk /dev/sda</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Welcome to fdisk (util-linux 2.29.2).</span></span>
<span class="line"><span>Changes will remain in memory only, until you decide to write them.</span></span>
<span class="line"><span>Be careful before using the write command.</span></span>
<span class="line"><span></span></span>
<span class="line"><span></span></span>
<span class="line"><span>Command (m for help): o</span></span>
<span class="line"><span>Created a new DOS disklabel with disk identifier 0x9c310964.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Command (m for help): n</span></span>
<span class="line"><span>Partition type</span></span>
<span class="line"><span>   p   primary (0 primary, 0 extended, 4 free)</span></span>
<span class="line"><span>   e   extended (container for logical partitions)</span></span>
<span class="line"><span>Select (default p): p</span></span>
<span class="line"><span>Partition number (1-4, default 1):</span></span>
<span class="line"><span>First sector (2048-1953525167, default 2048):</span></span>
<span class="line"><span>Last sector, +sectors or +size{K,M,G,T,P} (2048-1953525167, default 1953525167):</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Created a new partition 1 of type &#39;Linux&#39; and of size 931.5 GiB.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Command (m for help): p</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Disk /dev/sda: 931.5 GiB, 1000204886016 bytes, 1953525168 sectors</span></span>
<span class="line"><span>Units: sectors of 1 * 512 = 512 bytes</span></span>
<span class="line"><span>Sector size (logical/physical): 512 bytes / 512 bytes</span></span>
<span class="line"><span>I/O size (minimum/optimal): 512 bytes / 512 bytes</span></span>
<span class="line"><span>Disklabel type: dos</span></span>
<span class="line"><span>Disk identifier: 0x9c310964</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Device     Boot Start        End    Sectors   Size Id Type</span></span>
<span class="line"><span>/dev/sda1        2048 1953525167 1953523120 931.5G 83 Linux</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Command (m for help): w</span></span>
<span class="line"><span>The partition table has been altered.</span></span>
<span class="line"><span>Syncing disks.</span></span></code></pre></div><p>现在，我们将用 ext4 文件系统格式化新创建的分区 <code>/dev/sda1</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>pi@raspberrypi:~ $ sudo mkfs.ext4 /dev/sda1</span></span>
<span class="line"><span>mke2fs 1.43.4 (31-Jan-2017)</span></span>
<span class="line"><span>Discarding device blocks: done</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&lt;...&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Allocating group tables: done</span></span>
<span class="line"><span>Writing inode tables: done</span></span>
<span class="line"><span>Creating journal (1024 blocks): done</span></span>
<span class="line"><span>Writing superblocks and filesystem accounting information: done</span></span></code></pre></div><p>重复以上步骤后，让我们根据用途来对它们建立标签：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>pi@raspberrypi:~ $ sudo e2label /dev/sda1 data</span></span>
<span class="line"><span>pi@raspberrypi:~ $ sudo e2label /dev/sdb1 backup</span></span></code></pre></div><p>现在，让我们安装这些磁盘并存储一些数据。以我运营该系统超过一年的经验来看，当树莓派启动时（例如在断电后），USB 磁盘驱动器并不是总被挂载，因此我建议使用 autofs 在需要的时候进行挂载。</p><p>首先，安装 autofs 并创建挂载点：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>pi@raspberrypi:~ $ sudo apt install autofs</span></span>
<span class="line"><span>pi@raspberrypi:~ $ sudo mkdir /nas</span></span></code></pre></div><p>然后添加下面这行来挂载设备 <code>/etc/auto.master</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/nas    /etc/auto.usb</span></span></code></pre></div><p>如果不存在以下内容，则创建 <code>/etc/auto.usb</code>，然后重新启动 autofs 服务：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>data -fstype=ext4,rw :/dev/disk/by-label/data</span></span>
<span class="line"><span>backup -fstype=ext4,rw :/dev/disk/by-label/backup</span></span>
<span class="line"><span>pi@raspberrypi3:~ $ sudo service autofs restart</span></span></code></pre></div><p>现在你应该可以分别访问 <code>/nas/data</code> 以及 <code>/nas/backup</code> 磁盘了。显然，到此还不会令人太兴奋，因为你只是擦除了磁盘中的数据。不过，你可以执行以下命令来确认设备是否已经挂载成功：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>pi@raspberrypi3:~ $ cd /nas/data</span></span>
<span class="line"><span>pi@raspberrypi3:/nas/data $ cd /nas/backup</span></span>
<span class="line"><span>pi@raspberrypi3:/nas/backup $ mount</span></span>
<span class="line"><span>&lt;...&gt;</span></span>
<span class="line"><span>/etc/auto.usb on /nas type autofs (rw,relatime,fd=6,pgrp=463,timeout=300,minproto=5,maxproto=5,indirect)</span></span>
<span class="line"><span>&lt;...&gt;</span></span>
<span class="line"><span>/dev/sda1 on /nas/data type ext4 (rw,relatime,data=ordered)</span></span>
<span class="line"><span>/dev/sdb1 on /nas/backup type ext4 (rw,relatime,data=ordered)</span></span></code></pre></div><p>首先进入对应目录以确保 autofs 能够挂载设备。autofs 会跟踪文件系统的访问记录，并随时挂载所需要的设备。然后 <code>mount</code> 命令会显示这两个 USB 磁盘驱动器已经挂载到我们想要的位置了。</p><p>设置 autofs 的过程容易出错，如果第一次尝试失败，请不要沮丧。你可以上网搜索有关教程。</p><h3 id="挂载网络存储" tabindex="-1">挂载网络存储 <a class="header-anchor" href="#挂载网络存储" aria-label="Permalink to “挂载网络存储”">​</a></h3><p>现在你已经设置了基本的网络存储，我们希望将它安装到远程 Linux 机器上。这里使用 NFS 文件系统，首先在树莓派上安装 NFS 服务器：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>pi@raspberrypi:~ $ sudo apt install nfs-kernel-server</span></span></code></pre></div><p>然后，需要告诉 NFS 服务器公开 <code>/nas/data</code> 目录，这是从树莓派外部可以访问的唯一设备（另一个用于备份）。编辑 <code>/etc/exports</code> 添加如下内容以允许所有可以访问 NAS 云盘的设备挂载存储：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/nas/data *(rw,sync,no_subtree_check)</span></span></code></pre></div><p>更多有关限制挂载到单个设备的详细信息，请参阅 <code>man exports</code>。经过上面的配置，任何人都可以访问数据，只要他们可以访问 NFS 所需的端口：<code>111</code> 和 <code>2049</code>。我通过上面的配置，只允许通过路由器防火墙访问到我的家庭网络的 22 和 443 端口。这样，只有在家庭网络中的设备才能访问 NFS 服务器。</p><p>如果要在 Linux 计算机挂载存储，运行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>you@desktop:~ $ sudo mkdir /nas/data</span></span>
<span class="line"><span>you@desktop:~ $ sudo mount -t nfs &lt;raspberry-pi-hostname-or-ip&gt;:/nas/data /nas/data</span></span></code></pre></div>`,30)),n("p",null,[s[14]||(s[14]=a("同样，我建议使用 autofs 来挂载该网络设备。如果需要其他帮助，请参看 ",-1)),p(e,{href:"https://opensource.com/article/18/6/using-autofs-mount-nfs-shares"},{default:i(()=>[...s[13]||(s[13]=[a("如何使用 Autofs 来挂载 NFS 共享",-1)])]),_:1}),s[15]||(s[15]=a("。",-1))]),s[41]||(s[41]=n("p",null,[a("现在你可以在远程设备上通过 NFS 系统访问位于你树莓派 NAS 云盘上的数据了。在后面一篇文章中，我将介绍如何使用 "),n("code",null,"rsync"),a(" 自动将数据备份到第二个 USB 磁盘驱动器。你将会学到如何使用 "),n("code",null,"rsync"),a(" 创建增量备份，在进行日常备份的同时还能节省设备空间。")],-1)),s[42]||(s[42]=n("hr",null,null,-1)),n("p",null,[s[17]||(s[17]=a("via: ",-1)),p(e,{href:"https://opensource.com/article/18/7/network-attached-storage-Raspberry-Pi"},{default:i(()=>[...s[16]||(s[16]=[a("https://opensource.com/article/18/7/network-attached-storage-Raspberry-Pi",-1)])]),_:1})]),n("p",null,[s[22]||(s[22]=a("作者：",-1)),p(e,{href:"https://opensource.com/users/ntlx"},{default:i(()=>[...s[18]||(s[18]=[a("Manuel Dewald",-1)])]),_:1}),s[23]||(s[23]=a(" 选题：",-1)),p(e,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[19]||(s[19]=[a("lujun9972",-1)])]),_:1}),s[24]||(s[24]=a(" 译者：",-1)),p(e,{href:"https://github.com/jrglinux"},{default:i(()=>[...s[20]||(s[20]=[a("jrg",-1)])]),_:1}),s[25]||(s[25]=a(" 校对：",-1)),p(e,{href:"https://github.com/wxy"},{default:i(()=>[...s[21]||(s[21]=[a("wxy",-1)])]),_:1})]),n("p",null,[s[28]||(s[28]=a("本文由 ",-1)),p(e,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[26]||(s[26]=[a("LCTT",-1)])]),_:1}),s[29]||(s[29]=a(" 原创编译，",-1)),p(e,{href:"https://linux.cn/"},{default:i(()=>[...s[27]||(s[27]=[a("Linux中国",-1)])]),_:1}),s[30]||(s[30]=a(" 荣誉推出",-1))])])}const v=t(u,[["render",c]]);export{x as __pageData,v as default};
